228	/* Copies the part of the rectangle that lies inside both the source and the
229	 * destination (a pixmap, or the canvas when dst is NULL), so a huge width or
230	 * height costs nothing. All sums are in 64 bits. Between a colour source and a
231	 * colour destination, or two bitmaps, pixels are copied as they are; a bitmap
232	 * drawn on the canvas uses the GC's foreground and background. When source and
233	 * destination are the same pixmap and overlap, rows and columns are walked in
234	 * the order that reads each pixel before it is overwritten. Otherwise, with no
235	 * clip mask, colour rows are copied whole. */
236	static void copy_region(Display *dpy, GC gc, const struct XshimPixmap *src,
237	                        struct XshimPixmap *dst, int sx, int sy,
238	                        unsigned int w, unsigned int h, int dx, int dy) {
239	  Canvas *const out = dst ? (dst->depth == 16 ? &dst->canvas : NULL) : dpy->canvas;
240	  const int64_t dw = dst ? dst->w : dpy->canvas->w;
241	  const int64_t dh = dst ? dst->h : dpy->canvas->h;
242	  const int64_t i0 = max64(0, max64(-(int64_t)sx, -(int64_t)dx));
243	  const int64_t i1 = min64(w, min64((int64_t)src->w - sx, dw - dx));
244	  const int64_t j0 = max64(0, max64(-(int64_t)sy, -(int64_t)dy));
245	  const int64_t j1 = min64(h, min64((int64_t)src->h - sy, dh - dy));
246	  if (i1 <= i0 || j1 <= j0) return;
247	  const int same = dst == src;
248	  if (src->depth == 16 && out && !same && !gc->clip) {
249	    for (int64_t j = j0; j < j1; j++)
250	      canvas_paste_rect(out, (int)(dx + i0), (int)(dy + j), (int)(i1 - i0), 1,
251	                        src->canvas.px + (sy + j) * src->w + sx + i0);
252	    return;
253	  }
254	  const int reverse_x = same && dx > sx, reverse_y = same && dy > sy;
255	  for (int64_t jj = 0; jj < j1 - j0; jj++) {
256	    const int64_t j = reverse_y ? j1 - 1 - jj : j0 + jj;
257	    for (int64_t ii = 0; ii < i1 - i0; ii++) {
258	      const int64_t i = reverse_x ? i1 - 1 - ii : i0 + ii;
259	      const int64_t x = dx + i, y = dy + j;
260	      if (clipped_out(gc, x, y)) continue;
261	      const int64_t px = sx + i, py = sy + j;
262	      if (src->depth == 1) {
263	        const int bit = bit_at(src, (int)px, (int)py);
