352	static void join_at(Canvas *c, int ix, int iy, vec2 d1, vec2 d2, int w,
353	                    int style, uint16_t colour) {
354	  const float dot = d1.x * d2.x + d1.y * d2.y;
355	  const float cross = d1.x * d2.y - d1.y * d2.x;
356	  if (fabsf(cross) < 1e-4f && dot > 0) return;
