#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "core/canvas.h"
#include "hacks/registry.h"
#include "runner/hack_runner.h"

extern unsigned *g_hits;
extern long g_calls, g_pixels;

int main(int argc, char **argv) {
  const int frames = argc > 1 ? atoi(argv[1]) : 40;
  Canvas cv;
  if (canvas_init(&cv, 466, 466, malloc) != 0) return 1;
  g_hits = (unsigned *)calloc((size_t)cv.w * cv.h, sizeof(unsigned));
  HackRunner *r = runner_create(&cv);
  if (!r || runner_start(r, 0) != 0) return 1;
  long tot_paints = 0, tot_distinct = 0, tot_calls = 0;
  for (int f = 0; f < frames; f++) {
    memset(g_hits, 0, (size_t)cv.w * cv.h * sizeof(unsigned));
    g_calls = g_pixels = 0;
    runner_step(r);
    long distinct = 0, worst = 0;
    for (long i = 0; i < (long)cv.w * cv.h; i++) {
      if (g_hits[i]) distinct++;
      if ((long)g_hits[i] > worst) worst = g_hits[i];
    }
    tot_paints += g_pixels;
    tot_distinct += distinct;
    tot_calls += g_calls;
    if (g_pixels > 0 && (f < 12 || f % 10 == 0))
      printf("step %3d: stroker fills=%ld paints=%ld distinct=%ld ratio=%.2f worst=%ld\n", f,
             g_calls, g_pixels, distinct, (double)g_pixels / (double)(distinct ? distinct : 1), worst);
  }
  printf("TOTAL over %d steps: fills=%ld paints=%ld distinct(sum per step)=%ld ratio=%.2f\n",
         frames, tot_calls, tot_paints, tot_distinct,
         (double)tot_paints / (double)(tot_distinct ? tot_distinct : 1));
  runner_destroy(r);
  canvas_free(&cv);
  return 0;
}

