long g_calls, g_pixels;

void cfr_count(Canvas *c, int x, int y, int w, int h, uint16_t color) {
  int x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;
  int x1 = x + w > c->w ? c->w : x + w, y1 = y + h > c->h ? c->h : y + h;
  if (x0 < x1 && y0 < y1) {
    g_calls++;
    for (int yy = y0; yy < y1; yy++)
      for (int xx = x0; xx < x1; xx++) {
        g_hits[(long)yy * c->w + xx]++;
        g_pixels++;
      }
  }
  canvas_fill_rect(c, x, y, w, h, color);
}

