"""Writes celtic_counted.c: a scratch copy of celtic.c with call counters."""
import sys
from pathlib import Path

src = Path(sys.argv[1]).read_text()
out = Path(sys.argv[2])

old = "static void spline_value_at(Spline s, double *x, double *y, double t, int *segment)\n{\n  int si;"
assert old in src
src = src.replace(
    old,
    "long g_sva_calls;\n" + old.replace("{\n  int si;", "{\n  g_sva_calls++;\n  int si;"),
)

# Count XDrawLine calls, zero-length ones and exact repeats on the same GC.
head = '#include <math.h>\n#include "screenhack.h"\n#include "erase.h"\n'
assert head in src
probe = r'''
long g_line_calls, g_line_zero, g_line_repeat, g_ticks;
static int g_last[16][4];
static GC g_last_gc[16];
static int g_nlast;
static int counted_draw_line(Display *d, Drawable w, GC gc, int x1, int y1, int x2, int y2) {
  g_line_calls++;
  if (x1 == x2 && y1 == y2) g_line_zero++;
  int slot = -1;
  for (int i = 0; i < g_nlast; i++) if (g_last_gc[i] == gc) slot = i;
  if (slot < 0 && g_nlast < 16) { slot = g_nlast++; g_last_gc[slot] = gc; g_last[slot][0] = 1 << 30; }
  if (slot >= 0) {
    if (g_last[slot][0] == x1 && g_last[slot][1] == y1 && g_last[slot][2] == x2 && g_last[slot][3] == y2) g_line_repeat++;
    g_last[slot][0] = x1; g_last[slot][1] = y1; g_last[slot][2] = x2; g_last[slot][3] = y2;
  }
  return XDrawLine(d, w, gc, x1, y1, x2, y2);
}
#define XDrawLine counted_draw_line
'''
src = src.replace(head, head + probe, 1)

old_tick = "for (ticks=0;ticks<100 && t<1;ticks++) {"
assert old_tick in src
src = src.replace(old_tick, "for (ticks=0;ticks<100 && t<1;ticks++) { g_ticks++;")
out.write_text(src)

#include <stdio.h>
#include <stdlib.h>

#include "core/canvas.h"
#include "hacks/registry.h"
#include "runner/hack_runner.h"

extern long g_sva_calls, g_line_calls, g_line_zero, g_line_repeat, g_ticks;

int main(int argc, char **argv) {
  const int frames = argc > 1 ? atoi(argv[1]) : 40;
  const int seed = argc > 2 ? atoi(argv[2]) : 1;
  srandom((unsigned)seed);
  Canvas cv;
  if (canvas_init(&cv, 466, 466, malloc) != 0) return 1;
  HackRunner *r = runner_create(&cv);
  if (!r || runner_start(r, 0) != 0) return 1;
  long s0 = 0, l0 = 0, z0 = 0, r0 = 0, t0 = 0;
  for (int f = 0; f < frames; f++) {
    runner_step(r);
    if (f < 6 || f % 15 == 0)
      printf("step %3d: ticks=%ld spline_evals=%ld lines=%ld zero_len=%ld repeats=%ld\n", f,
             g_ticks - t0, g_sva_calls - s0, g_line_calls - l0, g_line_zero - z0,
             g_line_repeat - r0);
    s0 = g_sva_calls; l0 = g_line_calls; z0 = g_line_zero; r0 = g_line_repeat; t0 = g_ticks;
  }
  printf("TOTAL %d steps: ticks=%ld spline_evals=%ld lines=%ld zero_len=%ld (%.0f%%) repeats=%ld (%.0f%%)\n",
         frames, g_ticks, g_sva_calls, g_line_calls, g_line_zero,
         100.0 * g_line_zero / (g_line_calls ? g_line_calls : 1), g_line_repeat,
         100.0 * g_line_repeat / (g_line_calls ? g_line_calls : 1));
  runner_destroy(r);
  canvas_free(&cv);
  return 0;
}

