import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

import celtic_patch as cp  # noqa: E402

ROOT = Path(__file__).resolve().parents[2]
CELTIC = ROOT / "firmware" / "src" / "hacks" / "celtic" / "celtic.c"

SAMPLE = """\
static void spline_value_at(Spline s, double *x, double *y, double t, int *segment)
{
  int si;
  double tt;
  SplineSegment ss;
  si = floor(t*s->segments->nb_elements);
  tt = t*s->segments->nb_elements - si;
  assert(tt>=0 && tt<1);
  ss=s->segments->elements[si];

  *x = ss->x1*(1-tt);
}
"""


def test_the_position_is_worked_out_once_so_a_fused_multiply_cannot_disagree():
    out = cp.compute_spline_position_once(SAMPLE)
    assert out.count("t*s->segments->nb_elements") == 1
    assert "si = floor(pos);" in out
    assert "tt = pos - si;" in out


def test_the_index_and_the_fraction_are_clamped_instead_of_aborting():
    out = cp.compute_spline_position_once(SAMPLE)
    assert "assert(tt>=0 && tt<1);" not in out
    assert "if (si < 0) si = 0;" in out
    assert "if (si >= s->segments->nb_elements) si = s->segments->nb_elements - 1;" in out
    assert "if (tt < 0) tt = 0;" in out
    assert "if (tt >= 1) tt = 0.999999;" in out


def test_the_rest_of_the_function_is_untouched():
    out = cp.compute_spline_position_once(SAMPLE)
    assert out.startswith("static void spline_value_at(Spline s, double *x")
    assert "  ss=s->segments->elements[si];\n" in out
    assert "*x = ss->x1*(1-tt);" in out


def test_a_change_upstream_fails_loudly():
    with pytest.raises(ValueError, match="has upstream changed"):
        cp.compute_spline_position_once(SAMPLE.replace("floor(", "ceil("))


def test_a_source_without_the_lines_fails_loudly():
    with pytest.raises(ValueError, match="has upstream changed"):
        cp.compute_spline_position_once("int main(void) { return 0; }\n")


def test_the_copied_celtic_source_patches_cleanly():
    out = cp.compute_spline_position_once(CELTIC.read_text())
    assert "assert(tt>=0 && tt<1);" not in out
    assert out.count("si = floor(pos);") == 1

"""Makes Celtic's spline lookup safe in single precision.

spline_value_at picks a segment with `si = floor(t*n)` and then the position in
it with `tt = t*n - si`, and aborts unless 0 <= tt < 1. Computed in double
precision that holds. In float the compiler fuses the second multiply and the
subtraction (the S3's `madd.s`, and arm64 on the host), so `tt` uses the exact
product while `si` came from the product rounded to a float: t = 0.331093 with
3422 segments rounds to exactly 1133 and gives tt = -1.4e-5, and the abort
stopped the board.

The copied celtic.c stays byte-identical to upstream. The firmware build runs
this on its text before the float literal pass (firmware/patch_float_literals.py).
The product is worked out once, and the index and fraction are clamped, since
t just under 1 can round up to the segment count.

The replacement is checked, so a change upstream fails the build loudly.
"""

OLD = """\
  si = floor(t*s->segments->nb_elements);
  tt = t*s->segments->nb_elements - si;
  assert(tt>=0 && tt<1);
"""

NEW = """\
  double pos = t*s->segments->nb_elements;
  si = floor(pos);
  if (si < 0) si = 0;
  if (si >= s->segments->nb_elements) si = s->segments->nb_elements - 1;
  tt = pos - si;
  if (tt < 0) tt = 0;
  if (tt >= 1) tt = 0.999999;
"""


def compute_spline_position_once(source: str) -> str:
    found = source.count(OLD)
    if found != 1:
        raise ValueError(
            f"expected 1 spline_value_at lookup in celtic.c, found {found}; "
            "has upstream changed?"
        )
    return source.replace(OLD, NEW)

