      first_p = True;
      st = eraser_init (dpy, window);
    }

  now = (first_p ? st->start_time : double_time());
  duration = st->stop_time - st->start_time;

  st->prev_ratio = st->ratio;
  st->ratio = (now - st->start_time) / duration;

  if (st->ratio < 1.0)
    {
      st->fn (st);
      XSync (st->dpy, False);
    }
  else
    {
      eraser_free (st);
      st = 0;
    }
  return st;
