out.mkdir(exist_ok=True)

src = (root / ".pio/build/dump/generated/celtic_floatlit.c").read_text()

report = r'''
/* ---- scratch instrumentation ---- */
static int blk(int payload) { int b = ((payload + 3) / 4) * 4 + 4; return b < 16 ? 16 : b; }
static int arrblk(int nb_alloc) { return nb_alloc ? blk(nb_alloc * 4) : 0; }
static void celtic_report(struct state *st) {
  Graph g = st->graph;
  Pattern p = st->pattern;
  int N = g->nodes->nb_elements, E = g->edges->nb_elements;
  long est = 0;
  /* nodes: struct (12), its edge Array struct (16), its pointer array */
  for (int i = 0; i < N; i++) {
    Node n = g->nodes->elements[i];
    est += blk(12) + blk(16) + arrblk(n->edges->nb_allocated_elements);
  }
  est += (long)E * blk(16);                    /* edges */
  est += arrblk(g->nodes->nb_allocated_elements) + arrblk(g->edges->nb_allocated_elements);
  est += blk(4 * E) + (long)E * blk(8);        /* edge couple pointer array and pairs */
  int S = 0, SEG = 0;
  for (int i = 0; i < p->splines->nb_elements; i++) {
    Spline s = p->splines->elements[i];
    if (!s) continue;
    S++;
    SEG += s->segments->nb_elements;
    est += blk(8) + blk(16) + arrblk(s->segments->nb_allocated_elements) +
           (long)s->segments->nb_elements * blk(32);
  }
  est += arrblk(p->splines->nb_allocated_elements);
  static const char *names[] = {"polar", "grid", "kennicott", "triangle"};
  fprintf(stderr,
          "STAT type=%s margin=%ld edge=%lu orbits=%lu nodes=%lu N=%d E=%d splines=%d segs=%d est_heap=%ld\n",
          names[st->params.type], (long)(int)st->params.margin, st->params.edge_size,
          st->params.nb_orbits, st->params.nb_nodes_per_orbit, N, E, S, SEG, est);
}
static void celtic_force(struct state *st) {
  const char *t = getenv("CELTIC_TYPE"), *m = getenv("CELTIC_MARGIN"), *e = getenv("CELTIC_EDGE");
  if (t) st->params.type = (enum graph_type)atoi(t);
  if (m) st->params.margin = (unsigned long)(long)atoi(m);
  if (e) st->params.edge_size = (unsigned long)atoi(e);
  if (t && st->params.type == kennicott && st->params.edge_size > 0) {
    st->params.cluster_size = st->params.edge_size / 4.0 - 1;
  }
}
/* ---- end scratch instrumentation ---- */
'''

