229	/* Fills a convex polygon whose vertices are in pixel coordinates, where the
230	 * pixel at x, y has its centre at x + 0.5, y + 0.5. A pixel is drawn when its
231	 * centre is inside, the left and top edges excluded and the right and bottom
232	 * edges included. The vertices stay floats: canvas_fill_polygon takes ints,
233	 * which would move the edges of a thin line by up to half a pixel. */
234	static void fill_convex(Canvas *c, const float pts[][2], int n,
235	                        uint16_t colour) {
236	  float ymin = pts[0][1], ymax = ymin;
237	  for (int i = 1; i < n; i++) {
238	    ymin = fminf(ymin, pts[i][1]);
239	    ymax = fmaxf(ymax, pts[i][1]);
240	  }
241	  const wide_t y0 = max_w(0, (wide_t)floorf(ymin));
242	  const wide_t y1 = min_w((wide_t)c->h - 1, (wide_t)ceilf(ymax));
243	  for (wide_t y = y0; y <= y1; y++) {
244	    const float sy = (float)y + 0.5f;
245	    float xl = INFINITY, xr = -INFINITY;
246	    for (int i = 0, j = n - 1; i < n; j = i++) {
247	      const float yi = pts[i][1], yj = pts[j][1];
248	      if ((yi < sy && yj >= sy) || (yj < sy && yi >= sy)) {
249	        const float x = pts[i][0] + (sy - yi) / (yj - yi) * (pts[j][0] - pts[i][0]);
