loop_old = """  for (int i = 0; i < g_hack_count; i++) {
    if (kBaseline[i] == 0) continue;
    TEST_ASSERT_EQUAL_UINT64_MESSAGE(kBaseline[i], hash_after(i, 200),
                                     g_hacks[i]->name);
  }
}"""
loop_new = """  for (int i = 0; i < g_hack_count; i++) {
    if (kBaseline[i] == 0) continue;
    (void)hash_after(i, 200);
  }
}"""
hash_old = "static uint64_t hash_after(int index, int frames) {"
step_old = "    if (f % (frames / 4) == 0) chain = (chain ^ frame_hash()) * 0x100000001b3ull;\n"
assert test_original.count(loop_old) == 1 and test_original.count(hash_old) == 1
assert test_original.count(step_old) == 1


def instrumented(label):
    dump = f"""static void dump_frame(int index, int f) {{
  char path[300];
  snprintf(path, sizeof path, "{out}/{label}_%d_%d.raw", index, f);
  FILE *fp = fopen(path, "wb");
  for (long i = 0; i < (long)cv.w * cv.h; i++) {{
    uint16_t v = px_swap(cv.px[i]);
    fwrite(&v, sizeof v, 1, fp);
  }}
  fclose(fp);
}}

"""
    text = test_original.replace(loop_old, loop_new)
    text = text.replace(hash_old, dump + hash_old)
    text = text.replace(
        step_old,
        step_old + "    if (f % (frames / 4) == 0 && (index == 35 || index == 36 || index == 39 "
        "|| index == 45 || index == 68)) dump_frame(index, f);\n",
    )
    return text


env = dict(os.environ, PLATFORMIO_CORE_DIR=str(root / ".platformio"), NO_COLOR="1")
try:
    for label, stroke_text in (("old", stroke_unfixed), ("new", stroke_fixed)):
        stroke.write_text(stroke_text)
        test.write_text(instrumented(label))
        proc = subprocess.run(
            [str(root / ".venv/bin/pio"), "test", "-e", "native", "-f", "test_hacks"],
            cwd=root / "firmware", env=env, capture_output=True, text=True,
        )
        summary = [l for l in proc.stdout.splitlines() if "test cases" in l]
        print(label, summary[-1].strip() if summary else "no summary")
finally:
    stroke.write_text(stroke_fixed)
    test.write_text(test_original)
assert stroke.read_text() == stroke_fixed and test.read_text() == test_original
print("restored; frames:", len(list(out.glob("*.raw"))))
